import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.nio.charset.*;import javax.imageio.*;import game.*;import boss.*;import entity.*;import java.awt.*;import java.awt.image.*;
/** Exact existing assets/animations/world/UI/audio protection and beam combat-source equivalence. */
public class Phase3PreservationTest extends V2TestSupport {
 static String before(String p)throws Exception{return new String(Phase10PreservationSupport.archive(p,"PHASE3"),StandardCharsets.UTF_8).replace("\r\n","\n");}
 static String now(String p)throws Exception{return new String(Phase4PreservationSupport.previous(p,Files.readAllBytes(Path.of(p))),StandardCharsets.UTF_8).replace("\r\n","\n");}
 static String segment(String s,String a,String b){return s.substring(s.indexOf(a),s.indexOf(b,s.indexOf(a)));}
 public static void main(String[]args)throws Exception{
  var allowed=Phase3PreservationSupport.allowed();var m=Pattern.compile("\"([^\"]+)\":\\s*\"([a-f0-9]{64})\"").matcher(Files.readString(Path.of("docs/PHASE3_BASELINE.json")));int n=0;var changed=new TreeSet<String>();
  while(m.find()){String p=m.group(1),prior=m.group(2);byte[] bytes=Phase4PreservationSupport.previous(p,Files.readAllBytes(Path.of(p)));String h=ForestPreservationSupport.hash(bytes);check(h.equals(allowed.getProperty(p,prior)),"Exact prior or reviewed Phase3 revision "+p);if(!h.equals(prior))changed.add(p);check(ForestPreservationSupport.hash(Phase3PreservationSupport.previous(p,bytes)).equals(prior),"Authenticated recovery "+p);n++;}
  check(n==1751&&changed.equals(allowed.stringPropertyNames()),"Complete approved Phase2 inventory protected");
  var production=Set.of("src/game/GamePanel.java","src/game/SantaSkills.java","src/game/HealingPoint.java","src/game/Encounter.java","src/game/EncounterManager.java","src/ui/DialogueManager.java","src/boss/DarkTitan.java","src/boss/BossAttacks.java");for(String p:changed)if(p.startsWith("src/"))check(production.contains(p),"Only eight targeted production owners "+p);for(String p:changed)check(!p.startsWith("assets/")&&!p.startsWith("src/audio/")&&!p.startsWith(".vscode/"),"No original asset/audio/configuration changed");
  String p="src/boss/BossAttacks.java";check(segment(before(p),"    public void begin(","    private void effect(").equals(segment(now(p),"    public void begin(","    private void effect(")),"Entire attack creation, all timings, beam hitbox/range/direction/damage and collision execution remain byte-equivalent");
  p="src/boss/DarkTitan.java";check(segment(before(p),"    public String getAnimationName()","\n}").equals(segment(now(p),"    public String getAnimationName()","\n}")),"All Titan animation selection, frames, timing and drawing exact");
  String expectedTitan=before("src/boss/DarkTitan.java");
  expectedTitan=expectedTitan.replace("BossAttacks.Attack.DARK_FROST_BEAM,BossAttacks.Attack.GROUND_SLAM,BossAttacks.Attack.ICE_SPIKES}","BossAttacks.Attack.GROUND_SLAM,BossAttacks.Attack.DARK_FROST_BEAM,BossAttacks.Attack.GROUND_SLAM,BossAttacks.Attack.ICE_SPIKES}");
  expectedTitan=expectedTitan.replace("BossAttacks.Attack.BEAST_CHARGE,BossAttacks.Attack.DARK_FROST_BEAM,BossAttacks.Attack.ICE_SPIKES,BossAttacks.Attack.GROUND_SLAM}","BossAttacks.Attack.GROUND_SLAM,BossAttacks.Attack.BEAST_CHARGE,BossAttacks.Attack.DARK_FROST_BEAM,BossAttacks.Attack.GROUND_SLAM,BossAttacks.Attack.ICE_SPIKES}");
  expectedTitan=expectedTitan.replace("cooldown=phase==0?100:phase==1?80:65;","cooldown=phase==0?(pattern[choice%pattern.length]==BossAttacks.Attack.GROUND_SLAM?70:100):phase==1?80:65;");
  expectedTitan=expectedTitan.replace("    @Override public boolean tryAttackSanta","    /** Encounter-owned summoning is admitted only between complete attacks. */\n    public boolean canSummon(){return !isDefeated()&&entrance==0&&transition==0&&attacks.getAttack()==BossAttacks.Attack.NONE;}\n    public void prepareSummon(){if(canSummon())cooldown=Math.max(cooldown,150);}\n    @Override public boolean tryAttackSanta");
  check(expectedTitan.equals(now("src/boss/DarkTitan.java")),"Whole Titan source unchanged except exact approved patterns, pre-slam idle gap and neutral-only summon admission; HP, phases, movement, every animation and execution clock retained");
  p="src/game/SantaSkills.java";check(before(p).replace("COOLDOWN=90, STAR_COOLDOWN=60","COOLDOWN=180, STAR_COOLDOWN=60").equals(now(p)),"Entire SantaSkills owner identical except bomb cooldown constant");
  int pngs=0;for(String path:Phase3PreservationSupport.assets()){if(!path.endsWith(".png"))continue;var im=ImageIO.read(Path.of(path).toFile());check(im!=null&&im.getColorModel().hasAlpha(),"New PNG decodes with alpha "+path);int transparent=0,opaque=0;var colors=new HashSet<Integer>();for(int y=0;y<im.getHeight();y+=2)for(int x=0;x<im.getWidth();x+=2){int c=im.getRGB(x,y);if((c>>>24)==0)transparent++;if((c>>>24)>128){opaque++;colors.add(c);}}check(transparent>0&&opaque>30&&colors.size()>80,"Nonempty detailed illustrated pixels "+path);pngs++;}check(pngs==26,"16 smoke+8 beam frames and two sheets");
  for(int area=0;area<4;area++)Phase2UIPreservationSupport.frame(area,ForestLandmarkPreservationTest.raw(area));SantaBaseVisuals.prepareAsync().get();var panel=SantaBaseNavigationTest.opening();panel.setSize(1600,1280);Phase2UIPreservationSupport.frame(3,render(panel));panel.stopGame();check(true,"All neutral world/UI renders retain exact Phase2 pixels");
  var titan=new DarkTitan(200,200);var santa=new Santa(500,183);var a=titan.attacks();a.begin(BossAttacks.Attack.DARK_FROST_BEAM,titan,santa,java.util.List.of());var image=new BufferedImage(800,600,2);var g=image.createGraphics();for(int i=0;i<59;i++){a.update(titan,santa,java.util.List.of());a.draw(g);}check(santa.getHealth()==100&&a.getWarningFrames()==1,"Charging visuals never damage");int clock=a.getTicks();for(int i=0;i<20;i++)a.draw(g);check(a.getTicks()==clock,"VFX paints never advance combat clock");for(int i=0;i<7;i++)a.update(titan,santa,java.util.List.of());check(santa.getHealth()==78,"Original advancing24-half-width beam reaches once");for(int i=0;i<100;i++)a.update(titan,santa,java.util.List.of());check(a.getAttack()==BossAttacks.Attack.NONE&&santa.getHealth()==78,"Beam expires without repeated damage");g.dispose();
  check(SpiritTreeTransformation.DURATION==180&&EndingCutscene.SLEIGH_DURATION==360&&BossFallPresentation.FANG_DURATION==240&&BossFallPresentation.TITAN_DURATION==300,"All approved cinematic clocks unchanged");
  System.out.println("Phase3PreservationTest PASS "+checks+" source/asset/renderer/timing assertions");
 }
}
